<div class="grid stats-grid">${stat('Local profile',`${localScore}%`,'Saved checklist progress','✓')}${stat('Scheduled posts',String(scheduled),'Publishing queue','◷')}${stat('New leads',String(newLeads),'Current pipeline','♙')}${stat('Booking value',`₹${bookingValue.toLocaleString('en-IN')}`,`${bookings} active appointments`,'₹')}</div>
