function seo(){const saved=state.seoAudit,checks=saved?.checks||[['Title tag',true,'Demo title present'],['Meta description',false,'Run a local HTML audit'],['Single H1',true,'Demo structure'],['Mobile viewport',true,'Demo structure'],['Canonical URL',false,'Run a local HTML audit'],['Image ALT text',false,'Run a local HTML audit'],['JSON-LD schema',true,'LocalBusiness draft available']],score=saved?.score??57,passed=checks.filter(([,ok])=>ok).length,improvements=checks.length-passed;return `${heading('Be easier to find','SEO audit','Analyze page HTML locally and keep your latest structural SEO results.','<button class="primary-button" id="auditButton">↻ Run HTML audit</button>')}<div class="grid stats-grid">${stat('SEO score',`${score}/100`,saved?'Latest saved audit':'Starter baseline','⌁')}${stat('Passed',`${passed} checks`,'No action needed','✓')}${stat('Improvements',`${improvements} checks`,'Review recommended','!')}${stat('Last audit',saved?new Date(saved.date).toLocaleDateString():'Not run','Stored on this device','◷')}</div><section class="card"><div class="card-header"><div><h2 class="card-title">Technical checklist</h2><p class="card-subtitle">${saved?'Latest local HTML audit':'Starter baseline · run an audit to replace it'}</p></div></div>${checks.map(([name,ok,detail])=>`<div class="audit-row"><span class="audit-state ${ok?'':'warn'}">${ok?'✓':'!'}</span><div><b>${name}</b><p>${escapeHtml(detail)}</p></div><span class="pill ${ok?'green':'orange'}">${ok?'Passed':'Improve'}</span></div>`).join('')}</section>`}
