function crm(){let booked=state.leads.filter(l=>l.status==='Booked').length,follow=state.leads.filter(isLeadDue).length,newCount=state.leads.filter(l=>l.status==='New').length,conversion=state.leads.length?Math.round(booked/state.leads.length*100):0;return `${heading('Know every customer','Leads & customers','A simple pipeline for enquiries, follow-ups, and bookings.','<button class="ghost-button" id="exportLeads">Export CSV</button><label class="ghost-button file-button" for="importLeads">Import CSV</label><input id="importLeads" type="file" accept=".csv,text/csv" hidden><button class="primary-button" id="addLead">+ Add lead</button>')}<div class="grid stats-grid">${stat('Follow-ups due',String(follow),follow?'Needs attention':'Nothing overdue','◷')}${stat('New enquiries',String(newCount),'Current pipeline','♙')}${stat('Bookings won',String(booked),`${conversion}% conversion`,'✓')}${stat('Total contacts',String(state.leads.length),'Saved locally','♙')}</div><section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Contact</th><th>Source</th><th>Interested in</th><th>Next follow-up</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.leads.length?state.leads.map((l,i)=>`<tr title="${escapeHtml(l.notes||'')}"><td><b>${escapeHtml(l.name)}</b><br><small class="muted">${escapeHtml(l.date||'')}</small></td><td>${escapeHtml(l.phone||'—')}</td><td>${escapeHtml(l.source)}</td><td>${escapeHtml(l.service)}</td><td>${l.followUp?`<span class="pill ${isLeadDue(l)?'orange':'green'}">${escapeHtml(l.followUp)}${isLeadDue(l)?' · due':''}</span>`:'<span class="muted">Not set</span>'}</td><td><select data-lead-status="${i}"><option ${l.status==='New'?'selected':''}>New</option><option ${l.status==='Follow-up'?'selected':''}>Follow-up</option><option ${l.status==='Booked'?'selected':''}>Booked</option><option ${l.status==='Lost'?'selected':''}>Lost</option></select></td><td><button class="text-button" data-edit-lead="${i}">Edit</button> <button class="text-button" data-delete-lead="${i}">Delete</button></td></tr>`).join(''):'<tr><td colspan="7">No leads yet.</td></tr>'}</tbody></table></div></section>`}
