function analytics(){const visits=state.forecastData?.visits||[720,810,870,940,1080,1284],months=state.forecastMonths||['Jan','Feb','Mar','Apr','May','Jun'],latest=visits.at(-1)||0,previous=visits.at(-2)||latest,growth=previous?Math.round((latest-previous)/previous*100):0,bookings=state.appointments.filter(a=>a.status!=='Cancelled'),revenue=bookings.reduce((sum,a)=>sum+(Number(a.value)||0),0),chart=visits.slice(-7),max=Math.max(...chart,1),labels=months.slice(-chart.length);return `${heading('See what is working','Analytics overview','Live workspace metrics plus imported historical performance.','<button class="ghost-button" data-route="predictions">Import historical data</button><button class="ghost-button" data-action="placeholder">Connect Google Analytics</button>')}<div class="grid stats-grid">${stat('Website visits',latest.toLocaleString('en-IN'),state.forecastData?`${growth>=0?'↑':'↓'} ${Math.abs(growth)}% vs previous period`:'Demo history · import CSV','↗')}${stat('CRM leads',String(state.leads.length),'Current workspace total','♙')}${stat('Active bookings',String(bookings.length),'Confirmed and pending','✓')}${stat('Booking value',`₹${revenue.toLocaleString('en-IN')}`,'From active appointments','₹')}</div><div class="grid dashboard-grid"><section class="card"><div class="card-header"><div><h2 class="card-title">Website visit trend</h2><p class="card-subtitle">${state.forecastData?'Imported historical data':'Studio Salvadore demo history'}</p></div><span class="pill ${growth>=0?'green':'orange'}">${growth>=0?'+':''}${growth}%</span></div><div class="bar-chart">${chart.map(value=>`<div class="bar-group"><span class="bar orange" style="width:100%;height:${Math.max(5,Math.round(value/max*100))}%" title="${value.toLocaleString('en-IN')} visits"></span></div>`).join('')}</div><div class="chart-labels">${labels.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div></section><aside class="card"><h2 class="card-title">Data sources</h2><p class="card-subtitle">Current measurement readiness</p>${[['↗','Historical CSV',state.forecastData?`${visits.length} periods imported`:'Demo data'],['♙','CRM',`${state.leads.length} local leads`],['◫','Appointments',`${state.appointments.length} local records`],['G','Google Analytics 4','Not connected']].map((x,i)=>`<div class="integration"><span class="integration-logo">${x[0]}</span><div><b>${x[1]}</b><p>${x[2]}</p></div>${i===3?'<button class="text-button" data-action="placeholder">Set up</button>':`<span class="pill ${i&&'green'}">Active</span>`}</div>`).join('')}</aside></div>`}
