function credits(){let used=state.usage.reduce((sum,row)=>sum+(Number(row.credits)||0),0),limit=100,percent=Math.min(100,Math.round(used/limit*100));return `${heading('Stay in control','Credits & API usage','See how automation and AI usage affect your budget.')}<div class="grid dashboard-grid"><section class="credit-box"><div class="eyebrow">Local allowance</div><div style="font:800 38px Manrope;margin-top:8px">${used} <span style="font-size:16px;color:#aaa">/ ${limit}</span></div><p style="color:#aaa">Local workflow credits</p><div class="progress"><span style="width:${percent}%"></span></div><small>Browser-local tracking · estimated API cost ₹0</small></section><section class="card"><h2 class="card-title">Free-first guardrails</h2><ul class="checklist"><li><span class="check-dot">✓</span>Local generation enabled</li><li><span class="check-dot">✓</span>Usage limit shown at 100</li><li><span class="check-dot">✓</span>No paid API connected</li></ul></section></div><section class="card" style="margin-top:18px"><div class="card-header"><div><h2 class="card-title">Usage history</h2><p class="card-subtitle">Actions recorded in this browser</p></div><button class="text-button" id="clearUsage">Clear history</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Action</th><th>Provider</th><th>Credits</th></tr></thead><tbody>${state.usage.length?state.usage.map(row=>`<tr><td>${escapeHtml(row.date)}</td><td>${escapeHtml(row.action)}</td><td>Local engine</td><td>${row.credits}</td></tr>`).join(''):'<tr><td colspan="4">No tracked actions yet.</td></tr>'}</tbody></table></div></section>`}
function settings(){let b=state.business,e=escapeHtml;return `${heading('Your business foundation','Business settings','Keep this aligned with your website and Google Business Profile.','<button class="ghost-button" id="exportBackup">Export backup</button><label class="ghost-button file-button" for="importBackup">Import backup</label><input id="importBackup" type="file" accept="application/json,.json" hidden>')}<div class="settings-layout"><aside class="card settings-nav"><button class="active">Business profile</button><button>Brand voice</button><button>Locations</button><button>Integrations</button><button>Team</button></aside><section class="card"><div class="card-header"><div><h2 class="card-title">Business profile</h2><p class="card-subtitle">Used across content, local SEO, and reporting. Your workspace is stored on this device; export a backup before clearing browser data.</p></div></div><form id="settingsForm" class="form-grid"><div class="field full"><label>Business name</label><input name="name" value="${e(b.name)}"></div><div class="field"><label>Category</label><input name="category" value="${e(b.category)}"></div><div class="field"><label>Phone</label><input name="phone" value="${e(b.phone)}"></div><div class="field"><label>Email</label><input name="email" value="${e(b.email)}"></div><div class="field"><label>Website</label><input name="website" value="${e(b.website)}"></div><div class="field"><label>Google review URL</label><input name="reviewUrl" value="${e(b.reviewUrl)}" placeholder="https://g.page/r/…/review"></div><div class="field full"><label>Address / service area</label><input name="address" value="${e(b.address)}"></div><div class="field full"><label>Opening hours</label><input name="hours" value="${e(b.hours)}"></div><div class="field full"><label>Short description</label><textarea name="description">${e(b.description)}</textarea></div><div class="field full"><label>Brand voice</label><input name="tone" value="${e(b.tone)}"></div><div class="field full"><div><button class="primary-button">Save changes</button></div></div></form></section></div>`}
const views={dashboard,planner,scheduler,generator,seo,local:localSeo,analytics,predictions,crm,appointments,credits,settings};
function route(name){name=views[name]?name:'dashboard';location.hash=name;renderNav();updateShellStatus();$('#app').innerHTML=views[name]();$('#pageCrumb').textContent=titles[name];$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.route===name));$('#sidebar').classList.remove('open');$('#app').focus();bindPage();}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
function modal(title,body,submit='Save'){let d=$('#modal');$('#modalContent').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" value="cancel">×</button></div>${body}<div class="modal-actions"><button class="ghost-button" value="cancel">Cancel</button><button class="primary-button" value="default">${submit}</button></div>`;d.showModal();return d}
function notificationItems(){const due=state.leads.filter(isLeadDue).length,pending=state.appointments.filter(a=>a.status==='Pending').length,drafts=state.posts.filter(p=>p.status==='Draft'||p.date==='Unscheduled').length,local=state.localSeoChecks.filter(x=>!x).length;return [{route:'crm',icon:'♙',title:`${due} follow-up${due===1?'':'s'} due`,detail:'Review customers who need attention',count:due},{route:'appointments',icon:'◫',title:`${pending} appointment${pending===1?'':'s'} pending`,detail:'Confirm or reschedule bookings',count:pending},{route:'planner',icon:'▦',title:`${drafts} content draft${drafts===1?'':'s'}`,detail:'Finish and schedule planned content',count:drafts},{route:'local',icon:'⌖',title:`${local} local SEO task${local===1?'':'s'} open`,detail:'Improve Google Business readiness',count:local}].filter(item=>item.count)}
function updateShellStatus(){const items=notificationItems(),button=$('#notificationButton'),dot=button?.querySelector('i'),name=state.business.name||'MarketingMind Workspace',category=state.business.category||'Local business',initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase();if(button){button.title=items.length?`${items.length} action groups need attention`:'No pending notifications';if(dot)dot.hidden=!items.length}if($('#workspaceName'))$('#workspaceName').textContent=name;if($('#workspaceCategory'))$('#workspaceCategory').textContent=category;if($('#workspaceAvatar'))$('#workspaceAvatar').textContent=initials||'M';document.title=`MarketingMind AI — ${name}`}
function notificationModal(){const items=notificationItems(),body=items.length?`<div class="notification-list">${items.map(item=>`<button type="button" class="notification-item" data-notification-route="${item.route}"><span>${item.icon}</span><div><b>${item.title}</b><small>${item.detail}</small></div><strong>→</strong></button>`).join('')}</div>`:'<div class="empty-state"><span>✓</span><h3>You are all caught up</h3><p>No urgent workspace actions right now.</p></div>',d=modal('Action centre',body,'Close');$$('[data-notification-route]').forEach(button=>button.onclick=()=>{d.close();route(button.dataset.notificationRoute)});d.onsubmit=event=>{event.preventDefault();d.close()}}
function localSchema(){const business=state.business,schema={'@context':'https://schema.org','@type':business.category?.toLowerCase().includes('salon')?'BeautySalon':'LocalBusiness',name:business.name,description:business.description,telephone:business.phone,email:business.email,url:business.website,address:{'@type':'PostalAddress',streetAddress:business.address,addressCountry:'IN'},openingHours:business.hours};Object.keys(schema).forEach(key=>{if(schema[key]==='')delete schema[key]});return schema}
function schemaModal(){const json=JSON.stringify(localSchema(),null,2),d=modal('LocalBusiness JSON-LD',`<p class="muted">Review the business details, then add this JSON-LD inside your website’s &lt;head&gt;. Validate it before production use.</p><div class="field"><label>Generated schema</label><textarea id="schemaOutput" style="min-height:310px;font-family:monospace">${escapeHtml(json)}</textarea></div><div style="margin-top:12px"><button type="button" class="ghost-button" id="copySchema">Copy schema</button></div>`,'Download JSON');$('#copySchema').onclick=()=>navigator.clipboard?.writeText($('#schemaOutput').value).then(()=>toast('Schema copied'));d.onsubmit=event=>{event.preventDefault();downloadText($('#schemaOutput').value,'localbusiness-schema.json');d.close();toast('Schema downloaded')}}
function exportLocalSeoReport(){const items=['Business name matches your storefront','Primary category selected','Phone and opening hours added','Website link uses tracking tags','Services and prices completed','Business description added','20+ authentic customer reviews','Weekly photo or update published'],rows=[['MarketingMind Local SEO Report',''],['Generated',new Date().toISOString()],['Business',state.business.name],['Category',state.business.category],['Address',state.business.address],['Phone',state.business.phone],['Website',state.business.website],['Opening hours',state.business.hours],[],['Checklist item','Status'],...items.map((item,index)=>[item,state.localSeoChecks[index]?'Complete':'Open'])];downloadText(rows.map(row=>row.map(csvCell).join(',')).join('\n'),'marketingmind-local-seo-report.csv');toast('Local SEO report exported')}
function seoAuditModal(){let d=modal('Analyze page HTML',`<p class="muted">Open the page source of a website, copy the complete HTML, and paste it below. Analysis stays in this browser.</p><div class="field"><label>Page HTML</label><textarea id="auditHtml" style="min-height:280px;font-family:monospace" placeholder="<!doctype html>…" required></textarea></div>`,'Analyze SEO');d.onsubmit=event=>{event.preventDefault();const source=$('#auditHtml').value.trim();if(!source){toast('Paste page HTML first');return}const doc=new DOMParser().parseFromString(source,'text/html'),title=doc.querySelector('title')?.textContent.trim()||'',description=doc.querySelector('meta[name="description"]')?.content.trim()||'',h1=doc.querySelectorAll('h1').length,images=[...doc.querySelectorAll('img')],missingAlt=images.filter(image=>!image.hasAttribute('alt')||!image.getAttribute('alt').trim()).length,checks=[['Title tag',title.length>=20&&title.length<=65,title?`${title.length} characters`:'Missing'],['Meta description',description.length>=70&&description.length<=170,description?`${description.length} characters`:'Missing'],['Single H1',h1===1,`${h1} found`],['Mobile viewport',!!doc.querySelector('meta[name="viewport"]'),doc.querySelector('meta[name="viewport"]')?'Present':'Missing'],['Canonical URL',!!doc.querySelector('link[rel="canonical"]'),doc.querySelector('link[rel="canonical"]')?.href||'Missing'],['Image ALT text',missingAlt===0,images.length?`${missingAlt} of ${images.length} missing`:'No images found'],['JSON-LD schema',!!doc.querySelector('script[type="application/ld+json"]'),doc.querySelector('script[type="application/ld+json"]')?'Present':'Missing']],passed=checks.filter(check=>check[1]).length,score=Math.round(passed/checks.length*100);state.seoAudit={score,checks,date:new Date().toISOString()};save();logUsage('Local HTML SEO audit',1);d.close();let result=modal(`SEO audit · ${score}/100`,`<div class="score-row" style="margin-bottom:16px"><div class="score-ring" style="--score:${score}"><strong>${score}</strong></div><div><b>${passed} of ${checks.length} checks passed</b><p class="card-subtitle">Saved locally · review content quality manually.</p></div></div>${checks.map(([name,ok,detail])=>`<div class="audit-row"><span class="audit-state ${ok?'':'warn'}">${ok?'✓':'!'}</span><div><b>${name}</b><p>${escapeHtml(detail)}</p></div><span class="pill ${ok?'green':'orange'}">${ok?'Passed':'Improve'}</span></div>`).join('')}`,'Close');result.onsubmit=e=>{e.preventDefault();result.close();route('seo')}}}
function utmModal(){let d=modal('Build a campaign URL',`<div class="form-grid"><div class="field full"><label>Landing page URL</label><input id="utmUrl" type="url" value="${escapeHtml(state.business.website||'')}" placeholder="https://example.com/offer" required></div><div class="field"><label>Campaign source</label><input id="utmSource" value="instagram" placeholder="instagram, google, newsletter" required></div><div class="field"><label>Campaign medium</label><input id="utmMedium" value="social" placeholder="social, cpc, email" required></div><div class="field full"><label>Campaign name</label><input id="utmCampaign" placeholder="monsoon-hair-spa" required></div><div class="field"><label>Content label</label><input id="utmContent" placeholder="reel-a (optional)"></div><div class="field"><label>Search term</label><input id="utmTerm" placeholder="hair spa (optional)"></div></div>`,'Generate link');d.onsubmit=event=>{event.preventDefault();try{const url=new URL($('#utmUrl').value),set=(key,value)=>{if(value.trim())url.searchParams.set(key,value.trim().toLowerCase().replace(/\s+/g,'-'))};set('utm_source',$('#utmSource').value);set('utm_medium',$('#utmMedium').value);set('utm_campaign',$('#utmCampaign').value);set('utm_content',$('#utmContent').value);set('utm_term',$('#utmTerm').value);d.close();let result=modal('Campaign URL ready',`<div class="field"><label>Tracked URL</label><textarea id="utmOutput" style="min-height:130px">${escapeHtml(url.toString())}</textarea></div><p class="muted">Use the same naming convention across campaigns so GA4 reports stay clean.</p>`,'Copy link');result.onsubmit=e=>{e.preventDefault();navigator.clipboard?.writeText($('#utmOutput').value);logUsage('UTM campaign link',1);result.close();toast('Campaign URL copied')}}catch{toast('Enter a valid landing page URL')}}}
function contentModal(){let d=modal('Create content',`<div class="form-grid"><div class="field full"><label>Post idea</label><input id="newTitle" placeholder="What do you want to share?"></div><div class="field"><label>Channel</label><select id="newChannel"><option>Instagram</option><option>Facebook</option><option>Google Business</option></select></div><div class="field"><label>Publish date</label><input id="newDate" type="datetime-local"></div></div>`,'Add to planner');d.onsubmit=e=>{e.preventDefault();let title=$('#newTitle').value.trim();if(!title)return;state.posts.unshift({title,channel:$('#newChannel').value,status:'Draft',date:$('#newDate').value?new Date($('#newDate').value).toLocaleString():'Unscheduled',theme:'alt'});save();d.close();toast('Draft added to your planner');if(location.hash==='#planner')route('planner')};}
function editPostModal(index){let post=state.posts[index];if(!post)return;let d=modal('Edit content',`<div class="form-grid"><div class="field full"><label>Title</label><input id="editPostTitle" value="${escapeHtml(post.title)}" required></div><div class="field"><label>Channel</label><select id="editPostChannel">${['Instagram','Facebook','Google Business','Blog'].map(x=>`<option ${post.channel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select id="editPostStatus">${['Draft','Ready','Scheduled'].map(x=>`<option ${post.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Publish date and time</label><input id="editPostDate" type="datetime-local"></div><div class="field full"><label>Copy</label><textarea id="editPostCopy">${escapeHtml(post.copy||'')}</textarea></div></div>`,'Save content');d.onsubmit=e=>{e.preventDefault();let date=$('#editPostDate').value;state.posts[index]={...post,title:$('#editPostTitle').value.trim(),channel:$('#editPostChannel').value,status:$('#editPostStatus').value,date:date?new Date(date).toLocaleString():post.date,copy:$('#editPostCopy').value};save();d.close();route(location.hash.slice(1)||'planner');toast('Content updated')}}
function appointmentModal(){let d=modal('New appointment',`<div class="form-grid"><div class="field"><label>Customer</label><input id="appointmentCustomer" required></div><div class="field"><label>Service</label><input id="appointmentService" required></div><div class="field"><label>Team member</label><input id="appointmentStaff" placeholder="Optional"></div><div class="field"><label>Date and time</label><input id="appointmentDate" type="datetime-local" required></div><div class="field"><label>Estimated value ₹</label><input id="appointmentValue" type="number" min="0" value="0"></div><div class="field"><label>Status</label><select id="appointmentStatus"><option>Pending</option><option>Confirmed</option></select></div><div class="field full"><label><input id="appointmentLead" type="checkbox" checked> Add customer to CRM if not already present</label></div></div>`,'Save appointment');d.onsubmit=e=>{e.preventDefault();let customer=$('#appointmentCustomer').value.trim(),service=$('#appointmentService').value.trim(),staff=$('#appointmentStaff').value.trim(),date=$('#appointmentDate').value;if(hasAppointmentConflict(date,staff)&&!confirm('This team member already has a booking at this time. Save anyway?'))return;state.appointments.push({customer,service,staff,date,value:Math.max(0,Number($('#appointmentValue').value)||0),status:$('#appointmentStatus').value});if($('#appointmentLead').checked&&!state.leads.some(l=>l.name.toLowerCase()===customer.toLowerCase()))state.leads.unshift({name:customer,source:'Appointment',service,status:'Booked',date:'Today'});save();d.close();route('appointments');toast('Appointment saved')}}
function hasAppointmentConflict(date,staff,except=-1){if(!date||!staff)return false;return state.appointments.some((a,i)=>i!==except&&a.status!=='Cancelled'&&a.date===date&&(a.staff||'').toLowerCase()===staff.toLowerCase())}
function editAppointmentModal(index){const item=state.appointments[index];if(!item)return;let d=modal('Edit appointment',`<div class="form-grid"><div class="field"><label>Customer</label><input id="editAppointmentCustomer" value="${escapeHtml(item.customer)}" required></div><div class="field"><label>Service</label><input id="editAppointmentService" value="${escapeHtml(item.service)}" required></div><div class="field"><label>Team member</label><input id="editAppointmentStaff" value="${escapeHtml(item.staff||'')}"></div><div class="field"><label>Date and time</label><input id="editAppointmentDate" type="datetime-local" value="${escapeHtml(item.date)}" required></div><div class="field"><label>Estimated value ₹</label><input id="editAppointmentValue" type="number" min="0" value="${Number(item.value)||0}"></div><div class="field"><label>Status</label><select id="editAppointmentStatus">${['Pending','Confirmed','Completed','Cancelled'].map(x=>`<option ${item.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`,'Save changes');d.onsubmit=event=>{event.preventDefault();const date=$('#editAppointmentDate').value,staff=$('#editAppointmentStaff').value.trim();if(hasAppointmentConflict(date,staff,index)&&!confirm('This team member already has a booking at this time. Save anyway?'))return;state.appointments[index]={customer:$('#editAppointmentCustomer').value.trim(),service:$('#editAppointmentService').value.trim(),staff,date,value:Math.max(0,Number($('#editAppointmentValue').value)||0),status:$('#editAppointmentStatus').value};save();d.close();route('appointments');toast('Appointment updated')}}
function appointmentReminderModal(index){const item=state.appointments[index];if(!item)return;const when=new Date(item.date).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}),message=`Hello ${item.customer}, this is a reminder for your ${item.service} appointment at ${state.business.name} on ${when}${item.staff?` with ${item.staff}`:''}. ${state.business.address?`Location: ${state.business.address}. `:''}Please reply if you need to reschedule. We look forward to seeing you!`,d=modal('Appointment reminder',`<div class="field"><label>Customer message</label><textarea id="appointmentReminder" style="min-height:210px">${escapeHtml(message)}</textarea></div><p class="muted">Review the date and customer details before sending through your preferred messaging app.</p>`,'Copy reminder');d.onsubmit=event=>{event.preventDefault();navigator.clipboard?.writeText($('#appointmentReminder').value);logUsage('Appointment reminder',1);d.close();toast('Appointment reminder copied')}}
function isLeadDue(lead){if(!lead.followUp||['Booked','Lost'].includes(lead.status))return false;return lead.followUp<=new Date().toISOString().slice(0,10)}
