function leadFollowUpModal(index){const lead=state.leads[index];if(!lead)return;const message=`Hello ${lead.name}, thank you for your interest in ${lead.service||'our services'} at ${state.business.name}. Our team would be happy to answer your questions and help you choose the right option. Would you like us to reserve a convenient appointment time for you?${state.business.phone?` You can also reach us at ${state.business.phone}.`:''}`,d=modal('Lead follow-up message',`<div class="field"><label>Customer message</label><textarea id="leadFollowUpMessage" style="min-height:220px">${escapeHtml(message)}</textarea></div><p class="muted">Review the message and contact only customers who have consented to receive follow-ups.</p>`,'Copy message');d.onsubmit=event=>{event.preventDefault();navigator.clipboard?.writeText($('#leadFollowUpMessage').value);lead.date='Today';if(lead.status==='New')lead.status='Follow-up';logUsage('CRM follow-up message',1);save();d.close();route('crm');toast('Follow-up message copied')}}
