function integrationSetupModal(id){const guide=integrationGuides[id];if(!guide)return;const variables=guide.variables.join('\n'),d=modal(`Set up ${guide.name}`,`<div class="setup-steps"><div><span>1</span><p><b>Open Cloudflare Pages settings</b><br><small>Go to your MarketingMind project → Settings → Variables and Secrets.</small></p></div><div><span>2</span><p><b>Add the required names</b><br><small>Use Secret for private keys. Production and preview values can be managed separately.</small></p></div><div><span>3</span><p><b>Deploy and check again</b><br><small>After saving, redeploy once and return to Integration readiness.</small></p></div></div><div class="field"><label>Required variable names</label><textarea id="integrationVariables" readonly>${escapeHtml(variables)}</textarea></div><p class="integration-note">${escapeHtml(guide.note)}</p><a class="ghost-button setup-link" href="https://dash.cloudflare.com/" target="_blank" rel="noopener">Open Cloudflare dashboard ↗</a>`,'Copy variable names');d.onsubmit=event=>{event.preventDefault();navigator.clipboard?.writeText(variables);d.close();toast('Variable names copied — add your own secret values in Cloudflare')}}
function createLocalDraft(topic,type,goal,language,variant=0){
  const business=state.business.name,ctas={bookings:['Book your appointment today.','Reserve your preferred time now.','Message our team for a personalised consultation.'],offer:['Message us to claim the offer.','Book before the offer ends.','Ask our team for availability today.'],educate:['Save this tip and ask our team what suits you.','Share this with someone who needs it.','Book a consultation for personalised advice.'],awareness:['Follow us for more salon and self-care inspiration.','Discover more personalised care from our team.','Visit us and experience the difference.']},group=goal==='Get bookings'?'bookings':goal==='Promote an offer'?'offer':goal==='Educate customers'?'educate':'awareness',cta=ctas[group][variant%3];
  if(language==='Bengali')return [`${topic} নিয়ে ${business}-এর বিশেষ যত্ন।`,`আপনার ${topic} নিয়ে চিন্তা হচ্ছে? ${business}-এর টিম পাশে আছে।`,`নিজের যত্নে আজ একটু সময় দিন—${topic} নিয়ে ${business}-এর ব্যক্তিগত সেবা নিন।`][variant%3]+` আপনার চুল, ত্বক ও স্বস্তির প্রয়োজন বুঝে আমাদের টিম ব্যক্তিগতভাবে সেবা সাজায়। আজই যোগাযোগ করে আপনার সময় বুক করুন।\n\n#StudioSalvadore #KolkataSalon #SalonAndSpa`;
  if(language==='Hindi')return [`${topic} के लिए ${business} की खास देखभाल।`,`क्या आप ${topic} को लेकर परेशान हैं? ${business} की टीम आपकी मदद के लिए तैयार है।`,`अपने लिए थोड़ा समय निकालें—${topic} के लिए व्यक्तिगत देखभाल चुनें।`][variant%3]+` हमारी टीम आपकी ज़रूरत के अनुसार व्यक्तिगत सलाह और सेवा देती है। आज ही अपना अपॉइंटमेंट बुक करें।\n\n#StudioSalvadore #KolkataSalon #SalonAndSpa`;
  if(type==='Blog outline')return `Title: ${topic}\n\n1. Why this matters\n2. Common concerns and mistakes\n3. Professional care options\n4. At-home maintenance tips\n5. When to book a consultation\n\nConclusion: ${cta}`;
  const openers=type==='Facebook ad'?['Ready for a little transformation?','Your next confident look starts here.','Kolkata, it is time to treat yourself.']:type==='Google Business update'?['Now at Studio Salvadore:','A fresh reason to visit us this week:','New for our Kolkata community:']:['A little care can change the way your whole week feels. ✨','Your self-care reminder has arrived. ✨','Good hair and calm moments begin with thoughtful care. ✨'],opener=openers[variant%3];
  return `${opener}\n\n${topic}. At ${business}, our team combines thoughtful consultation with personalised salon and spa care, so every visit feels confidently yours. ${cta}\n\n#StudioSalvadore #KolkataSalon #SalonAndSpa`;
}
function renderServerDraft(draft,topic,type,goal,language,model){const out=$('#generatedOutput'),channel=type.startsWith('Instagram')?'Instagram':type.startsWith('Facebook')?'Facebook':type.startsWith('Google')?'Google Business':'Blog';out.style.display='block';out.innerHTML=`<div class="card-header"><div><h2 class="card-title">Server AI draft</h2><p class="card-subtitle">${escapeHtml(model||'OpenAI')} · review every claim before publishing</p></div><div><button class="ghost-button" id="copyServerDraft">Copy</button> <button class="primary-button" id="saveServerDraft">Save to planner</button></div></div><textarea id="serverDraftText" style="width:100%;min-height:210px;font-size:15px;line-height:1.7">${escapeHtml(draft)}</textarea><div class="content-meta" style="margin-top:12px"><span>${escapeHtml(type)} · ${escapeHtml(goal)} · ${escapeHtml(language)}</span><button class="text-button" id="scheduleServerDraft">Schedule instead →</button></div>`;$('#copyServerDraft').onclick=()=>navigator.clipboard?.writeText($('#serverDraftText').value).then(()=>toast('Server draft copied'));$('#saveServerDraft').onclick=()=>{state.posts.unshift({title:topic,copy:$('#serverDraftText').value,channel,status:'Draft',date:'Unscheduled',theme:'alt'});save();toast('Server draft saved to planner')};$('#scheduleServerDraft').onclick=()=>{let d=modal('Schedule server draft',`<div class="field"><label>Publish date and time</label><input id="serverDraftDate" type="datetime-local" required></div>`,'Schedule');d.onsubmit=e=>{e.preventDefault();state.posts.unshift({title:topic,copy:$('#serverDraftText').value,channel,status:'Scheduled',date:new Date($('#serverDraftDate').value).toLocaleString(),theme:'third'});save();d.close();toast('Server draft added to publishing queue')}}}
