function drawForecastChart(history,baseline,scenario,format,label){const el=$('#forecastChart'),w=Math.max(560,el.clientWidth||760),h=310,p={l:58,r:24,t:24,b:42},all=[...history,...baseline,...scenario],min=Math.min(...all)*.88,max=Math.max(...all)*1.1,total=history.length+baseline.length,x=i=>p.l+i*(w-p.l-p.r)/(total-1),y=v=>p.t+(max-v)*(h-p.t-p.b)/(max-min),path=arr=>arr.map((v,i)=>`${i?'L':'M'} ${x(i)} ${y(v)}`).join(' '),futureStart=history.length-1,fullBase=[history.at(-1),...baseline],fullScenario=[history.at(-1),...scenario],ticks=Array.from({length:5},(_,i)=>min+(max-min)*i/4);el.innerHTML=`<svg viewBox="0 0 ${w} ${h}" aria-hidden="true"><rect class="forecast-zone" x="${x(futureStart)}" y="${p.t}" width="${w-p.r-x(futureStart)}" height="${h-p.t-p.b}"></rect>${ticks.map(v=>`<line class="grid-line" x1="${p.l}" y1="${y(v)}" x2="${w-p.r}" y2="${y(v)}"></line><text class="axis-label" x="${p.l-9}" y="${y(v)+4}" text-anchor="end">${format(v)}</text>`).join('')}<line class="axis-line" x1="${p.l}" y1="${h-p.b}" x2="${w-p.r}" y2="${h-p.b}"></line><path class="chart-line actual-line" d="${path(history)}"></path><path class="chart-line baseline-line" d="${fullBase.map((v,i)=>`${i?'L':'M'} ${x(futureStart+i)} ${y(v)}`).join(' ')}"></path><path class="chart-line scenario-line" d="${fullScenario.map((v,i)=>`${i?'L':'M'} ${x(futureStart+i)} ${y(v)}`).join(' ')}"></path>${scenario.map((v,i)=>`<circle class="scenario-point" cx="${x(history.length+i)}" cy="${y(v)}" r="4"><title>Month ${i+1}: ${format(v)} ${label}</title></circle>`).join('')}<text class="axis-caption" x="${p.l}" y="${h-13}">6 months actual</text><text class="axis-caption" x="${w-p.r}" y="${h-13}" text-anchor="end">${baseline.length} months predicted</text><text class="forecast-label" x="${x(futureStart)+10}" y="${p.t+17}">FORECAST</text></svg>`}
function drawChannelChart(total,budget){const channels=[['Google',.42],['Instagram',.31],['Website',.17],['Referral',.10]],adjust=1+budget*.002;$('#channelChart').innerHTML=channels.map(([name,share])=>{const value=Math.round(total*share*adjust),width=Math.round(share*100);return `<div class="channel-row"><div><b>${name}</b><span>${value} leads · ${width}%</span></div><div class="channel-track"><span style="width:${width}%"></span></div></div>`}).join('')}
function linearTrend(values){const n=values.length,sumX=n*(n-1)/2,sumY=values.reduce((a,b)=>a+b,0),sumXY=values.reduce((a,b,i)=>a+b*i,0),sumXX=values.reduce((a,b,i)=>a+i*i,0),den=n*sumXX-sumX*sumX,slope=den?(n*sumXY-sumX*sumY)/den:0;return {slope,intercept:(sumY-slope*sumX)/n}}
function parseForecastCsv(text){const rows=text.trim().split(/\r?\n/).map(r=>r.split(',').map(v=>v.trim())),headers=rows.shift().map(x=>x.toLowerCase()),required=['month','leads','revenue','visits'];if(!required.every(x=>headers.includes(x)))throw new Error('CSV needs month, leads, revenue and visits columns');if(rows.length<4)throw new Error('Import at least 4 months of data');const index=Object.fromEntries(required.map(x=>[x,headers.indexOf(x)])),data={leads:[],revenue:[],visits:[]},months=[];rows.forEach((row,i)=>{months.push(row[index.month]);['leads','revenue','visits'].forEach(key=>{const value=Number(row[index[key]]);if(!Number.isFinite(value)||value<0)throw new Error(`Invalid ${key} value on row ${i+2}`);data[key].push(value)})});return {months,data}}
function parseCsvLine(line){const cells=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'&&quoted&&line[i+1]==='"'){value+='"';i++}else if(char==='"'){quoted=!quoted}else if(char===','&&!quoted){cells.push(value.trim());value=''}else value+=char}cells.push(value.trim());return cells}
function parseLeadsCsv(text){const rows=text.trim().split(/\r?\n/).filter(Boolean).map(parseCsvLine),headers=rows.shift()?.map(x=>x.toLowerCase()),required=['name','source','service'];if(!headers||!required.every(x=>headers.includes(x)))throw new Error('CSV needs name, source and service columns');const at=key=>headers.indexOf(key),get=(row,key)=>at(key)>=0?row[at(key)]||'':'',valid=['New','Follow-up','Booked','Lost'];const leads=rows.map((row,index)=>{const name=get(row,'name').trim();if(!name)throw new Error(`Missing name on row ${index+2}`);const status=get(row,'status')||'New';return {name,phone:get(row,'phone'),source:get(row,'source')||'Imported',service:get(row,'service')||'Not specified',status:valid.includes(status)?status:'New',date:get(row,'date')||'Imported',followUp:get(row,'followup'),notes:get(row,'notes')}});if(!leads.length)throw new Error('No lead rows found');return leads}
function csvCell(value){const text=String(value??'');return /[",\n]/.test(text)?`"${text.replaceAll('"','""')}"`:text}
function toIcsDate(date){return date.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}
function downloadText(text,name){const type=name.endsWith('.json')?'application/json':name.endsWith('.ics')?'text/calendar':'text/csv',blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function clamp(value,min,max){return Math.max(min,Math.min(max,value))}
